// CSD_RATIONALE_BEGIN
// This strategy aims to solve math word problems involving arithmetic operations on symbolic quantities.
// It uses a combination of constrained and unconstrained steps to ensure the generated solution is both grammatically correct and semantically meaningful.
// The strategy iteratively generates tokens, applying grammar constraints and penalizing invalid options to guide the model towards a valid solution.
// CSD_RATIONALE_END

var currentConstrained: Prefix := [];
var steps: nat := 0;

while steps < maxSteps
invariant 0 <= steps <= maxSteps
decreases maxSteps - steps
{
    // Check if we have reached the end-of-sequence token
    if helpers.Contains(helpers.PrefixToString(generated), eosToken.ToString()) {
        break;
    }

    // Use ConstrainedStep to generate a token constrained by the grammar rules
    var next := helpers.ConstrainedStep(lm, parser, prompt, currentConstrained);

    // Add the generated token to the current constrained prefix
    currentConstrained := currentConstrained + [next];

    // Update the generated sequence
    generated := generated + [next];

    // Increment the step counter
    steps := steps + 1;
}

// Set the final cost
cost := helpers.cost;

