attempts.strategy_code:
// CSD_RATIONALE_BEGIN
// This strategy uses a hybrid approach to generate a valid sequence of tokens based on the given parser constraints and language model logits. It alternates between constrained and unconstrained steps to balance exploration and exploitation. The strategy ensures that the generated sequence adheres to the grammar rules while also exploring possible extensions.
// CSD_RATIONALE_END

var currentConstrained: Prefix := [];
var steps: nat := 0;
var insideConstrained: bool := true;

while steps < maxSteps
invariant 0 <= steps <= maxSteps
decreases maxSteps - steps, if insideConstrained then 1 else 0
{
    // Check if we have reached the end-of-sequence token
    if helpers.Contains(helpers.PrefixToString(generated), eosToken.ToString()) {
        break;
    }

    // Alternate between constrained and unconstrained steps
    if insideConstrained {
        // Use ConstrainedStep to generate a token constrained by the grammar rules
        var next := helpers.ConstrainedStep(lm, parser, prompt, currentConstrained);
        currentConstrained := currentConstrained + [next];
        generated := generated + [next];
    } else {
        // Use UnconstrainedStep to generate a token without grammar constraint
        var next := helpers.UnconstrainedStep(lm, prompt, generated);
        generated := generated + [next];
    }

    // Toggle the insideConstrained flag
    insideConstrained := !insideConstrained;

    // Update the step counter
    steps := steps + 1;
}

// Set the final cost
cost := helpers.cost;

