    var next, wasConstrained := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);

    if wasConstrained {
        // If the next token is grammar-valid, add it to the generated sequence
        currentConstrained := currentConstrained + [next];
        generated := generated + [next];
