        // If the next token is grammar-invalid, fall back to an unconstrained step
        next := helpers.UnconstrainedStep(lm, prompt, generated);
        generated := generated + [next];
    }

    // Increment the step counter
    steps := steps + 1;
}

// Set the final cost
